//! ♻️ Original SQLite fields retire through actual supplied physical authority.
use super::*;
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress,retirement::{RetireOwned,controlled::ControlledRetirement}};
fn fixture()->serde_json::Value{serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap()}
fn row(f:&serde_json::Value)->SqliteRow{let t=&f["table"];SqliteRow{rowid:t["rowid"].as_i64().unwrap(),values:vec![SqliteValue::Integer(t["integer"].as_i64().unwrap()),SqliteValue::Real(t["real"].as_f64().unwrap()),SqliteValue::Text(t["text"].as_str().unwrap().into()),SqliteValue::Null,SqliteValue::Blob(serde_json::from_value(t["blob"].clone()).unwrap())]}}
fn table(f:&serde_json::Value)->SqliteTable{SqliteTable{name:f["table"]["name"].as_str().unwrap().into(),sql:f["table"]["sql"].as_str().unwrap().into(),rows:vec![row(f)]}}
fn row_backing(row:&SqliteRow)->usize{row.values.capacity()*std::mem::size_of::<SqliteValue>()+row.values.iter().map(|value|match value{SqliteValue::Text(text)=>text.capacity(),SqliteValue::Blob(bytes)=>bytes.capacity(),_=>0}).sum::<usize>()}
fn table_backing(table:&SqliteTable)->usize{table.name.capacity()+table.sql.capacity()+table.rows.capacity()*std::mem::size_of::<SqliteRow>()+table.rows.iter().map(row_backing).sum::<usize>()}
fn retire<T:RetireOwned>(source:T,backing:usize,pointers:impl Fn(&T)->[usize;4],f:&serde_json::Value){
 use std::cell::Cell;use std::sync::atomic::{AtomicUsize,Ordering};
 let grant:RetainedCloneGrant=serde_json::from_value(f["grant"].clone()).unwrap();let denied:RetainedCloneGrant=serde_json::from_value(f["deniedGrant"].clone()).unwrap();let initial=pointers(&source);let(admitted,born,freed)=crate::test_allocation::observe_backing(||ControlledRetirement::new(source));assert_eq!((born,freed),(0,0));let mut owner=admitted.unwrap_or_else(|(error,_)|panic!("{error}"));
 let(step,born,freed)=crate::test_allocation::observe_backing(||owner.step(denied).unwrap());assert_eq!((born,freed),(0,0));assert_eq!(step.progress(),RetainedCloneProgress::default());assert_eq!(pointers(owner.original().unwrap()),initial);
 let live=Cell::new(false);let ledger=AtomicUsize::new(0);let mut callback=|_|live.get();let mut allocation=|request:semio_framework_value::native_decoding::NativeDecodeAllocation|{assert_eq!(request.owned_bytes,ledger.load(Ordering::Relaxed));ledger.store(request.next_owned_bytes,Ordering::Relaxed);Ok(())};let mut native=semio_framework_value::NativeDecodeControl::new_forwarded(f["nativeMaximumBytes"].as_u64().unwrap()as usize,&mut callback,&mut allocation);let(error,born,freed)=crate::test_allocation::observe_backing(||native.checkpoint().unwrap_err());assert_eq!(error.kind,ValueRefusalKind::Canceled);assert_eq!((born,freed),(0,0));assert_eq!(pointers(owner.original().unwrap()),initial);live.set(true);
 let mut total=RetainedCloneProgress::default();let mut allocated=0usize;let mut released=0usize;
 for _ in 0..f["maximumTurns"].as_u64().unwrap(){if owner.terminal_is_empty(){break}let remaining=RetainedCloneGrant{maximum_items:grant.maximum_items-total.copied_items,maximum_copy_bytes:grant.maximum_copy_bytes-total.copied_bytes,maximum_capacity_bytes:grant.maximum_capacity_bytes-total.retained_capacity_bytes,maximum_release_bytes:grant.maximum_release_bytes-total.released_bytes,maximum_depth:grant.maximum_depth};assert!(owner.next_depth_demand().unwrap()<=remaining.maximum_depth);let capacity=owner.next_capacity_byte_demand(remaining.maximum_copy_bytes).unwrap();assert!(capacity<=remaining.maximum_capacity_bytes);assert!(owner.next_release_byte_demand().unwrap()<=remaining.maximum_release_bytes);native.checkpoint().unwrap();native.charge(capacity).unwrap();let(step,birth,release)=crate::test_allocation::observe_backing(||owner.step(remaining).unwrap());assert!(step.progress().fits(remaining));assert_eq!((birth,release),(step.progress().retained_capacity_bytes,step.progress().released_bytes));total=total.checked_add(step.progress()).unwrap();allocated+=birth;released+=release;assert_eq!(native.owned_bytes(),ledger.load(Ordering::Relaxed));}
 assert!(owner.terminal_is_empty());assert_eq!(released,backing+allocated);assert_eq!(crate::test_allocation::observe_backing(||drop(owner)),((),0,0));println!("[DEBUG] Original SQLite field {} pointerPreserved=true zeroEffectDenial=true originalPortEveryReserve=true cumulativeFiveAxis=true actualAllocated={allocated} actualReleased={released}",std::any::type_name::<T>());
}
#[test]
fn original_sqlite_fields_and_outcome_retire_actual_backing_with_independent_fixture_outputs(){
 use std::io::Write;use std::process::{Command,Stdio};let f=fixture();let database=SqliteDatabase{tables:vec![table(&f)]};let limits=&f["sqliteLimits"];let limits=SqliteDatabaseLimits{max_file_bytes:limits["maximumFileBytes"].as_u64().unwrap()as usize,max_value_bytes:limits["maximumValueBytes"].as_u64().unwrap()as usize,max_allocation_bytes:limits["maximumAllocationBytes"].as_u64().unwrap()as usize,max_schema_bytes:limits["maximumSchemaBytes"].as_u64().unwrap()as usize,max_rows:limits["maximumRows"].as_u64().unwrap()as usize,max_columns:limits["maximumColumns"].as_u64().unwrap()as usize,max_tables:limits["maximumTables"].as_u64().unwrap()as usize,max_pages:limits["maximumPages"].as_u64().unwrap()as usize};let observed=std::cell::Cell::new(0usize);let mut progress=|event:SqliteSnapshotProgress|{observed.set(observed.get()+1);event.completed<=event.total};let ledger=std::sync::atomic::AtomicUsize::new(0);let mut original_port=|request:semio_framework_value::native_encoding::NativeEncodeAllocation|{assert_eq!(request.owned_bytes,ledger.load(std::sync::atomic::Ordering::Relaxed));assert_eq!(request.maximum_bytes,limits.max_allocation_bytes);ledger.store(request.next_owned_bytes,std::sync::atomic::Ordering::Relaxed);Ok(())};let mut control=SqliteSnapshotControl::new_forwarded(&mut progress,limits,&mut original_port);let bytes=export_sqlite_database_controlled(&database,&mut control).unwrap();assert_eq!(control.forwarded_owned_bytes(),ledger.load(std::sync::atomic::Ordering::Relaxed));assert!(observed.get()>0);let script="import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));console.log(JSON.stringify(d.query(process.argv.at(-1)).all()));d.close();";let mut child=Command::new("bun").args(["-e",script,f["query"].as_str().unwrap()]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));assert_eq!(serde_json::from_slice::<serde_json::Value>(&output.stdout).unwrap(),f["queryResult"]);assert_eq!(serde_json::to_value(database.tables[0].rows[0].text(2).unwrap()).unwrap(),f["table"]["text"]);
 let backing=database.tables.capacity()*std::mem::size_of::<SqliteTable>()+database.tables.iter().map(table_backing).sum::<usize>();retire(database,backing,|db|[db.tables.as_ptr()as usize,db.tables[0].rows.as_ptr()as usize,db.tables[0].rows[0].values.as_ptr()as usize,db.tables[0].rows[0].text(2).unwrap().as_ptr()as usize],&f);let value=table(&f);let backing=table_backing(&value);retire(value,backing,|table|[table.name.as_ptr()as usize,table.sql.as_ptr()as usize,table.rows.as_ptr()as usize,table.rows[0].values.as_ptr()as usize],&f);let value=row(&f);let backing=row_backing(&value);retire(value,backing,|row|[row.values.as_ptr()as usize,row.text(2).unwrap().as_ptr()as usize,row.blob(4).unwrap().as_ptr()as usize,0],&f);
 for value in row(&f).values{let backing=match &value{SqliteValue::Text(text)=>text.capacity(),SqliteValue::Blob(bytes)=>bytes.capacity(),_=>0};retire(value,backing,|value|match value{SqliteValue::Text(text)=>[text.as_ptr()as usize,0,0,0],SqliteValue::Blob(bytes)=>[bytes.as_ptr()as usize,0,0,0],_=>[0;4]},&f);}
 assert_eq!(<semio_framework_io_schema::IoOutcome<semio_framework_diagnostic::TextError> as RetireOwned>::controlled_retirement_supported(),<semio_framework_diagnostic::TextError as RetireOwned>::controlled_retirement_supported()&&<Vec<semio_framework_diagnostic::Diagnostic> as RetireOwned>::controlled_retirement_supported());
 let diagnostic=semio_framework_diagnostic::Diagnostic::error("fixture.original.sqlite",serde_json::from_value(f["diagnostic"]["span"].clone()).unwrap(),f["diagnostic"]["message"].as_str().unwrap());let outcome=semio_framework_io_schema::IoOutcome{value:f["table"]["text"].as_str().unwrap().to_owned(),diagnostics:vec![diagnostic]};assert_eq!(serde_json::to_value(&outcome.value).unwrap(),f["table"]["text"]);assert_eq!(serde_json::to_value(&outcome.diagnostics[0].message).unwrap(),f["diagnostic"]["message"]);let backing=outcome.value.capacity()+outcome.diagnostics.capacity()*std::mem::size_of::<semio_framework_diagnostic::Diagnostic>()+outcome.diagnostics[0].code.0.capacity()+outcome.diagnostics[0].message.capacity();retire(outcome,backing,|outcome|[outcome.value.as_ptr()as usize,outcome.diagnostics.as_ptr()as usize,outcome.diagnostics[0].message.as_ptr()as usize,outcome.diagnostics[0].code.0.as_ptr()as usize],&f);println!("[DEBUG] Original SQLite field factory independentBunSqlite=true independentSerde=true actualDiagnosticFields=true fixedOriginalPolicy=true");
}
